function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // brain
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // thought bubble
  ctx.beginPath();
  ctx.arc(W/2 + 100 + 20 * Math.sin(t), H/2 - 50, 30, 0, 2 * Math.PI);
  ctx.stroke();

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2, H - 100, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 80);
  ctx.lineTo(W/2, H - 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 60);
  ctx.lineTo(W/2 - 20, H - 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 60);
  ctx.lineTo(W/2 + 20, H - 40);
  ctx.stroke();

  // emotion wave
  ctx.beginPath();
  ctx.moveTo(0, H - 20);
  for (let i = 0; i < W; i++) {
    ctx.lineTo(i, H - 20 - 10 * Math.sin(i / 50 + t));
  }
  ctx.stroke();

  ctx.restore();
}
